WITH cleaned AS (SELECT *, ROUND(quantity, 2) AS quantity_rounded FROM inventory WHERE last_restock >= '2023-09-01') SELECT store_id, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, APPROX_PERCENTILE(quantity_rounded, 0.9) AS quantity_rounded_p90, MIN(quantity) AS min_quantity, COUNT(*) AS num_rows, GROUPING_ID() AS gid FROM cleaned GROUP BY ROLLUP (store_id) ORDER BY quantity_rounded_p90 DESC NULLS FIRST;
